const params = $input.first().json.query;
if (!params || typeof params !== 'object' || Array.isArray(params)
    || !Object.prototype.hasOwnProperty.call(params, 'query')
    || typeof params.query !== 'string') {
  return [{json: {statusCode: 400, body: {error: {
    code: 'INVALID_REQUEST',
    message: 'Передайте один строковый параметр query. Для полного списка используйте query=.'
  }}}}];
}
return [{json: {query: params.query}}];

const request = $input.first().json;
if (request.statusCode !== undefined) return [{json: request}];

// Dataset from string-validator/ui/items.json. Input is never trimmed or truncated.
const items = [
  {id: '1', name: 'Alpha'},
  {id: '2', name: 'Beta'},
  {id: '3', name: 'Gamma'},
  {id: '4', name: 'Delta'},
  {id: '5', name: 'Omega'}
];
const query = request.query;
const allowedCharacter = /^[a-zA-Z0-9\s]$/u;
const valid = query.length <= 40
  && Array.from(query).every(character => allowedCharacter.test(character));
if (!valid) {
  return [{json: {statusCode: 400, body: {error: {
    code: 'INVALID_FILTER',
    message: 'Недопустимый фильтр. Используйте латинские буквы, цифры и пробельные символы, до 40 символов.'
  }}}}];
}
const lowerQuery = query.toLowerCase();
const result = query === '' ? items
  : items.filter(item => item.name.toLowerCase().includes(lowerQuery));
return [{json: {statusCode: 200, body: {items: result}}}];
